<script type="text/javascript">

    function katakanaCheck(f){
        var st = f.value;
        var zenkaku = "０１２３４５６７８９＋‐－ー＃￥＆．，：＊　";
        zenkaku += "ァアィイゥウェエォオカガキギクグケゲコゴサザシジスズセゼソゾタダチヂッツヅテデトド";
        zenkaku += "ナニヌネノハバパヒビピフブプヘベペホボポマミムメモャヤュユョヨラリルレロヮワヰヱヲンヴヵヶ";
        zenkaku += "ＡＢＣＤＥＦＧＨＩＪＫＬＭＮＯＰＱＲＳＴＵＶＷＸＹＺａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ";
        var reg = new RegExp("[^" + zenkaku + "]","g");
        if (st.match(reg) != null){
            alert("指定可能な文字以外が指定されています。\n\n【指定可能な文字】\n全角カナ、全角英数字\n全角記号（＋‐－ー＃￥＆．，：＊）、全角空白");
            f.focus();
        }
    }

    function katakanaNameCheck(f){
        var st = f.value;
        var zenkaku = "　ァアィイゥウェエォオカガキギクグケゲコゴサザシジスズセゼソゾタダチヂッツヅテデトド";
        zenkaku += "ナニヌネノハバパヒビピフブプヘベペホボポマミムメモャヤュユョヨラリルレロワンヴヲ";
        zenkaku += "‐－ー";
        var reg = new RegExp("[^" + zenkaku + "]","g");
        if (st.match(reg) != null){
            alert("指定可能な文字以外が指定されています。\n\n【指定可能な文字】\n全角カナ、全角記号（‐－ー）、全角空白");
            f.focus();
        }
    }

    function keitaiCtl(f){
        if (f.J89_賃金形態_月日時間給.value == "月給" || f.J89_賃金形態_月日時間給.value == "日給" || f.J89_賃金形態_月日時間給.value == "時間給") {
            f.J90_賃金形態_その他.value = "";
        }
    }

    function teateumuCtl(f){
        var teate = document.getElementsByName("J94_通勤手当の有無");
        for(var i=0;i<teate.length;i++) {
            if (teate[i].checked && teate[i].value == "無") {
                f.J95_通勤手当の期間.value = "";
                f.J96_通勤手当の期間_その他.value = "";
            }
        }
    }

    function kikanCtl1(f){
        var teate = document.getElementsByName("J94_通勤手当の有無");
        if (f.J95_通勤手当の期間.value != "") {
            for(var i=0;i<teate.length;i++) {
                if (teate[i].value == "有") {
                    teate[i].checked = true;
                }
            }
            if (f.J95_通勤手当の期間.value == "毎月" || f.J95_通勤手当の期間.value == "３か月" || f.J95_通勤手当の期間.value == "６か月") {
                f.J96_通勤手当の期間_その他.value = "";
            }
        }
    }

    function kikanCtl2(f){
        var teate = document.getElementsByName("J94_通勤手当の有無");
        if (f.J96_通勤手当の期間_その他.value != "") {
            for(var i=0;i<teate.length;i++) {
                if (teate[i].value == "有") {
                    teate[i].checked = true;
                }
            }
            f.J95_通勤手当の期間.value = "その他";
        }
    }

</script>

